parameters.jsCode:
const body = $input.first().json.body;
const required = ['client_name', 'client_email', 'service_type', 'account_manager'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}
return [{
  json: {
    valid: true,
    clientId: `CL-${Date.now()}`,
    clientName: body.client_name.trim(),
    clientEmail: body.client_email.trim(),
    clientCompany: body.client_company || '',
    clientPhone: body.client_phone || '',
    serviceType: body.service_type.trim(),
    packageTier: body.package_tier || 'standard',
    accountManager: body.account_manager.trim(),
    accountManagerEmail: body.account_manager_email || null,
    startDate: body.start_date || new Date().toISOString().split('T')[0],
    contractValue: parseFloat(body.contract_value) || null,
    currency: body.currency || 'USD',
    projectDetails: (body.project_details || '').slice(0, 800),
    specificNeeds: (body.specific_needs || '').slice(0, 500),
    notifySlack: body.notify_slack_channel || null,
    requestedAt: new Date().toISOString()
  }
}];

