  },
  "internal_handoff_note": {
    "subject": "internal subject line",
    "body": "note to the account manager and team summarizing who this client is, what they need, key context, and what the first week should look like. Under 150 words."
  },
  "onboarding_checklist": [
    {
      "phase": "Week 1 / Week 2 / Month 1 / Ongoing",
      "owner": "Account Manager / Client / Both",
      "task": "specific task description",
      "notes": "why this matters or how to do it"
    }
  ],
  "kickoff_meeting_agenda": [
    {
      "item": "agenda item",
      "duration_minutes": 10,
      "purpose": "what this segment accomplishes"
    }
  ],
  "success_metrics": ["3-5 specific measurable outcomes that would indicate successful onboarding for this service type"],
  "red_flags_to_watch": ["2-3 early warning signs that onboarding is going poorly for this type of client/service"]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let materials;
try {
  materials = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
const input = $('Validate Input').first().json;
materials._client = {
  clientId: input.clientId,
  clientName: input.clientName,
  clientEmail: input.clientEmail,
  clientCompany: input.clientCompany,
  serviceType: input.serviceType,
  accountManager: input.accountManager,
  accountManagerEmail: input.accountManagerEmail,
  startDate: input.startDate,
  notifySlack: input.notifySlack
};
return [{ json: materials }];

